import { useState, useEffect, useCallback, useRef } from "react";

const _lnk = document.createElement("link");
_lnk.href = "https://fonts.googleapis.com/css2?family=Bebas+Neue&family=IBM+Plex+Mono:wght@400;600&family=Space+Grotesk:wght@400;500;600;700&display=swap";
_lnk.rel = "stylesheet";
document.head.appendChild(_lnk);

const WP_URL = "https://vooomiegroup.com";
const WP_API = `${WP_URL}/wp-json/wp/v2/posts?per_page=100&orderby=date&order=desc&_fields=id,title,link,categories,date,excerpt,jetpack_featured_media_url,content`;
const LOGO   = "data:image/png;base64,";
const ADMIN_PW = "vooomie2024";

const CAT = {
  174:{name:"Politics",  color:"#ff4d4d", icon:"🏛️"},
  175:{name:"Funny",     color:"#ffd700", icon:"😂"},
  176:{name:"Lifestyle", color:"#ff69b4", icon:"✨"},
  177:{name:"Sports",    color:"#00e5ff", icon:"⚽"},
  178:{name:"Tech",      color:"#7fff00", icon:"💻"},
  179:{name:"Celebrity", color:"#ff8c00", icon:"⭐"},
  180:{name:"Crime",     color:"#ff6347", icon:"🚨"},
  181:{name:"Business",  color:"#00fa9a", icon:"💰"},
  182:{name:"Trends",    color:"#b388ff", icon:"🔥"},
};
const PLATFORMS = {
  TikTok:"#ff4d4d", Instagram:"#ff69b4", WhatsApp:"#25D366",
  Telegram:"#229ED9", "Twitter/X":"#1DA1F2", Facebook:"#1877F2", YouTube:"#FF0000"
};
const SOURCES = ["Pulse.ng","Vanguard","BellaNaija","Channels TV","Premium Times",
  "Reddit/Nigeria","Google Trends NG","TheCable","Naija247news","Notjustok",
  "BBC Africa","Reddit/Africa","Reddit/WorldNews"];

const clean = t => (t||"").replace(/&#(\d+);/g,(_,n)=>String.fromCharCode(n)).replace(/&amp;/g,"&").replace(/&quot;/g,'\"').replace(/&#8217;/g,"'").replace(/&#8230;/g,"...").replace(/<[^>]+>/g,"");
const ago = d => { const s=Math.floor((Date.now()-new Date(d))/1000); if(s<60)return s+"s"; if(s<3600)return Math.floor(s/60)+"m"; if(s<86400)return Math.floor(s/3600)+"h"; return Math.floor(s/86400)+"d"; };
const fmt = n => n>=1e6?(n/1e6).toFixed(1)+"M":n>=1000?(n/1000).toFixed(1)+"K":String(n);
const rnd = (a,b) => Math.floor(Math.random()*(b-a+1))+a;
const imgUrl = cat => `https://source.unsplash.com/800x450/?${encodeURIComponent(cat||"nigeria")},news`;
const hasVideo = p => !!(p.content?.rendered||"").match(/youtube|tiktok|youtu\.be|iframe.*video/i)||
  !!(p.title?.rendered||"").toLowerCase().match(/watch|video|viral video|footage/);

// ── HOOKS ─────────────────────────────────────────────────────────────────────
function useIsMobile() {
  const [mobile, setMobile] = useState(window.innerWidth < 768);
  useEffect(() => {
    const h = () => setMobile(window.innerWidth < 768);
    window.addEventListener("resize", h);
    return () => window.removeEventListener("resize", h);
  }, []);
  return mobile;
}

// ── SHARED COMPONENTS ─────────────────────────────────────────────────────────
const Dot = ({color="#39ff14",size=8,active=true}) => (
  <span style={{display:"inline-block",width:size,height:size,borderRadius:"50%",flexShrink:0,
    background:active?color:"#2a2a2a",
    boxShadow:active?`0 0 ${size}px ${color},0 0 ${size*2}px ${color}44`:"none",
    animation:active?"pulse 1.4s ease-in-out infinite":"none"}}/>
);

const Badge = ({text,color,size=10}) => (
  <span style={{display:"inline-flex",alignItems:"center",padding:"3px 9px",borderRadius:20,
    fontSize:size,fontFamily:"'IBM Plex Mono'",fontWeight:700,letterSpacing:.5,
    color,border:`1px solid ${color}55`,background:`${color}18`,whiteSpace:"nowrap"}}>
    {text}
  </span>
);

const ScoreRing = ({score,size=56}) => {
  const color = score>=85?"#39ff14":score>=70?"#ffd700":"#ff8c00";
  const r=size/2-5, circ=2*Math.PI*r, dash=(score/100)*circ;
  return (
    <div style={{position:"relative",width:size,height:size,flexShrink:0}}>
      <svg width={size} height={size} style={{transform:"rotate(-90deg)"}}>
        <circle cx={size/2} cy={size/2} r={r} fill="none" stroke="#1a1a1a" strokeWidth="3.5"/>
        <circle cx={size/2} cy={size/2} r={r} fill="none" stroke={color} strokeWidth="3.5"
          strokeDasharray={`${dash} ${circ}`} strokeLinecap="round"
          style={{filter:`drop-shadow(0 0 4px ${color}88)`,transition:"stroke-dasharray .6s"}}/>
      </svg>
      <div style={{position:"absolute",inset:0,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center"}}>
        <span style={{fontFamily:"'Bebas Neue'",fontSize:size*.3,color,lineHeight:1}}>{score}</span>
        <span style={{fontFamily:"'IBM Plex Mono'",fontSize:size*.12,color:"#555"}}>VIRAL</span>
      </div>
    </div>
  );
};

const StatCard = ({label,value,sub,color="#39ff14",icon}) => (
  <div style={{background:"#0d0d0d",border:"1px solid #1e1e1e",borderRadius:12,padding:"16px 18px",position:"relative",overflow:"hidden"}}>
    <div style={{position:"absolute",top:0,left:0,right:0,height:2,background:color,opacity:.8}}/>
    <div style={{fontFamily:"'IBM Plex Mono'",fontSize:11,color:"#555",letterSpacing:1,marginBottom:6}}>{icon} {label}</div>
    <div style={{fontFamily:"'Bebas Neue'",fontSize:34,color,letterSpacing:1,lineHeight:1}}>{value}</div>
    {sub&&<div style={{fontFamily:"'IBM Plex Mono'",fontSize:10,color:"#444",marginTop:4}}>{sub}</div>}
  </div>
);


// ── POST READER POPUP ─────────────────────────────────────────────────────────
function PostReader({post, onClose}) {
  const catId = post.categories?.[0]||182;
  const cat   = CAT[catId]||CAT[182];
  const title = clean(post.title?.rendered||"");
  const body  = post.content?.rendered||post.excerpt?.rendered||"";
  const img   = post.jetpack_featured_media_url||null;
  const isVid = hasVideo(post);
  const [loading, setLoading] = useState(true);
  const [fullContent, setFullContent] = useState(null);
  const sheetRef = useRef(null);
  const startY = useRef(0);

  // Fetch full post content
  useEffect(()=>{
    const fetchFull = async()=>{
      try {
        const res = await fetch(
          `${WP_URL}/wp-json/wp/v2/posts/${post.id}?_fields=content,excerpt`,
          {cache:"no-store"}
        );
        if(res.ok){
          const d = await res.json();
          setFullContent(d.content?.rendered||body);
        } else {
          setFullContent(body);
        }
      } catch(e){ setFullContent(body); }
      setLoading(false);
    };
    fetchFull();
    document.body.style.overflow = "hidden";
    return () => { document.body.style.overflow = ""; };
  },[post.id]);

  // Keyboard close
  useEffect(()=>{
    const h = e => { if(e.key==="Escape") onClose(); };
    window.addEventListener("keydown", h);
    return ()=>window.removeEventListener("keydown", h);
  },[onClose]);

  // Touch swipe down to close
  const handleTouchStart = e => { startY.current = e.touches[0].clientY; };
  const handleTouchEnd = e => {
    const diff = e.changedTouches[0].clientY - startY.current;
    if(diff > 80) onClose(); // swipe down 80px = close
  };

  const shareUrl = post.link||"";
  const shareText = encodeURIComponent(title.slice(0,100));

  return (
    <div
      onClick={e=>{ if(e.target===e.currentTarget) onClose(); }}
      style={{
        position:"fixed",inset:0,background:"#000000bb",zIndex:9999,
        display:"flex",alignItems:"flex-end",justifyContent:"center",
        backdropFilter:"blur(3px)",WebkitBackdropFilter:"blur(3px)",
        animation:"fadeIn .2s ease",touchAction:"none",
      }}>
      <style>{`
        @keyframes fadeIn{from{opacity:0}to{opacity:1}}
        @keyframes slideUp{from{transform:translateY(100%)}to{transform:translateY(0)}}
        .wp-content img{width:100%!important;height:auto!important;border-radius:8px;margin:10px 0;display:block}
        .wp-content p{margin-bottom:12px;line-height:1.75;color:#ccc;font-size:15px}
        .wp-content h1,.wp-content h2,.wp-content h3{color:#fff;margin:18px 0 8px;font-size:18px}
        .wp-content a{color:#39ff14;text-decoration:underline}
        .wp-content iframe{width:100%!important;max-height:220px;border-radius:8px;display:block}
        .wp-content figure{margin:12px 0}
        .wp-content blockquote{border-left:3px solid #39ff14;padding:8px 14px;margin:12px 0;background:#0d0d0d;border-radius:0 8px 8px 0;color:#aaa}
        .wp-content ul,.wp-content ol{padding-left:18px;margin-bottom:12px;color:#ccc}
        .wp-content li{margin-bottom:5px;line-height:1.6;font-size:14px}
        .wp-content div[style]{max-width:100%!important}
      `}</style>

      {/* Bottom Sheet */}
      <div
        ref={sheetRef}
        onTouchStart={handleTouchStart}
        onTouchEnd={handleTouchEnd}
        style={{
          background:"#0a0a0a",
          borderRadius:"20px 20px 0 0",
          width:"100%",
          maxWidth:720,
          maxHeight:"92vh",
          display:"flex",
          flexDirection:"column",
          animation:"slideUp .35s cubic-bezier(.32,.72,0,1)",
          border:"1px solid #222",
          borderBottom:"none",
          boxShadow:"0 -24px 80px #00000099",
          overflowY:"hidden",
          WebkitOverflowScrolling:"touch",
        }}>

        {/* Drag handle — visual cue to swipe down */}
        <div style={{display:"flex",justifyContent:"center",padding:"10px 0 4px",flexShrink:0}}>
          <div style={{width:40,height:4,background:"#333",borderRadius:2}}/>
        </div>

        {/* Header */}
        <div style={{padding:"8px 16px 12px",borderBottom:"1px solid #141414",flexShrink:0}}>
          <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:8}}>
            <div style={{display:"flex",gap:6,alignItems:"center",flexWrap:"wrap",flex:1,marginRight:10}}>
              <Badge text={cat.name} color={cat.color} size={10}/>
              {isVid&&<Badge text="▶ VIDEO" color="#ff4d4d" size={10}/>}
              <span style={{fontFamily:"'IBM Plex Mono'",fontSize:10,color:"#444"}}>{ago(post.date)} ago</span>
            </div>
            {/* Big close button — easy to tap on mobile */}
            <button
              onClick={onClose}
              style={{
                background:"#1e1e1e",border:"none",color:"#aaa",
                borderRadius:"50%",width:36,height:36,cursor:"pointer",
                fontSize:18,display:"flex",alignItems:"center",justifyContent:"center",
                flexShrink:0,WebkitTapHighlightColor:"transparent",
                touchAction:"manipulation",
              }}>✕</button>
          </div>
          <div style={{fontSize:17,fontWeight:700,lineHeight:1.35,color:"#fff"}}>{title}</div>
        </div>

        {/* Scrollable body */}
        <div style={{overflowY:"auto",flex:1,padding:"0 16px 24px",WebkitOverflowScrolling:"touch"}}>

          {/* Featured image */}
          {img&&(
            <div style={{margin:"14px 0",borderRadius:12,overflow:"hidden",position:"relative"}}>
              <img src={img} alt={title}
                style={{width:"100%",display:"block",maxHeight:220,objectFit:"cover"}}
                onError={e=>{e.target.parentNode.style.display="none";}}/>
              <div style={{position:"absolute",bottom:8,right:8}}>
                <ScoreRing score={post._score||75} size={44}/>
              </div>
            </div>
          )}

          {/* Article content */}
          {loading?(
            <div style={{padding:"32px 0",textAlign:"center"}}>
              <div style={{fontFamily:"'IBM Plex Mono'",fontSize:12,color:"#39ff14",
                animation:"pulse 1.4s infinite"}}>Loading article...</div>
            </div>
          ):(
            <div
              className="wp-content"
              dangerouslySetInnerHTML={{__html: fullContent||body}}
              style={{paddingTop:8,fontSize:15,lineHeight:1.7}}/>
          )}

          {/* Source + Read button */}
          <div style={{marginTop:16,padding:"12px 14px",background:"#0d0d0d",borderRadius:10,
            border:"1px solid #1a1a1a",display:"flex",justifyContent:"space-between",alignItems:"center"}}>
            <div>
              <div style={{fontFamily:"'IBM Plex Mono'",fontSize:9,color:"#444",marginBottom:2}}>SOURCE</div>
              <div style={{fontFamily:"'IBM Plex Mono'",fontSize:11,color:"#39ff14"}}>vooomiegroup.com</div>
            </div>
            <a href={post.link} target="_blank" rel="noreferrer"
              style={{background:"#39ff1422",border:"1px solid #39ff1444",color:"#39ff14",
                borderRadius:8,padding:"8px 14px",fontFamily:"'IBM Plex Mono'",
                fontSize:11,fontWeight:700,textDecoration:"none",
                WebkitTapHighlightColor:"transparent",touchAction:"manipulation"}}>
              READ ON SITE ↗
            </a>
          </div>

          {/* Share buttons */}
          <div style={{marginTop:14}}>
            <div style={{fontFamily:"'IBM Plex Mono'",fontSize:10,color:"#444",letterSpacing:1,marginBottom:10}}>
              SHARE THIS STORY
            </div>
            <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8}}>
              {[
                {label:"Twitter/X", color:"#1DA1F2", icon:"𝕏",
                  url:`https://twitter.com/intent/tweet?text=${shareText}&url=${encodeURIComponent(shareUrl)}&via=VOOOMIETrends`},
                {label:"WhatsApp", color:"#25D366", icon:"💬",
                  url:`https://wa.me/?text=${shareText}%20${encodeURIComponent(shareUrl)}`},
                {label:"Facebook", color:"#1877F2", icon:"f",
                  url:`https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(shareUrl)}`},
                {label:"Telegram", color:"#229ED9", icon:"✈️",
                  url:`https://t.me/share/url?url=${encodeURIComponent(shareUrl)}&text=${shareText}`},
              ].map(s=>(
                <a key={s.label} href={s.url} target="_blank" rel="noreferrer"
                  style={{display:"flex",alignItems:"center",justifyContent:"center",gap:6,
                    padding:"10px 12px",background:`${s.color}18`,
                    border:`1px solid ${s.color}44`,borderRadius:10,color:s.color,
                    fontFamily:"'IBM Plex Mono'",fontSize:11,fontWeight:700,
                    textDecoration:"none",WebkitTapHighlightColor:"transparent",
                    touchAction:"manipulation"}}>
                  <span>{s.icon}</span>{s.label}
                </a>
              ))}
            </div>
            {/* Copy link — full width */}
            <button
              onClick={()=>{
                if(navigator.share){
                  navigator.share({title,url:shareUrl}).catch(()=>{});
                } else {
                  navigator.clipboard?.writeText(shareUrl)
                    .then(()=>alert("Link copied!"))
                    .catch(()=>alert(shareUrl));
                }
              }}
              style={{width:"100%",marginTop:8,display:"flex",alignItems:"center",
                justifyContent:"center",gap:8,padding:"11px",
                background:"#b388ff18",border:"1px solid #b388ff44",
                borderRadius:10,color:"#b388ff",fontFamily:"'IBM Plex Mono'",
                fontSize:11,fontWeight:700,cursor:"pointer",
                WebkitTapHighlightColor:"transparent",touchAction:"manipulation"}}>
              🔗 {navigator.share?"Share Story":"Copy Link"}
            </button>
          </div>

          {/* View all */}
          <div style={{marginTop:16,textAlign:"center"}}>
            <a href={`${WP_URL}/vooomietrends`} target="_blank" rel="noreferrer"
              style={{fontFamily:"'IBM Plex Mono'",fontSize:11,color:"#39ff14",
                textDecoration:"none",WebkitTapHighlightColor:"transparent"}}>
              View all trending stories on VOOOMIE ↗
            </a>
          </div>
        </div>
      </div>
    </div>
  );
}


const BarRow = ({label,value,color,pct}) => (
  <div style={{marginBottom:12}}>
    <div style={{display:"flex",justifyContent:"space-between",marginBottom:4}}>
      <span style={{fontFamily:"'IBM Plex Mono'",fontSize:11,color:"#666"}}>{label}</span>
      <span style={{fontFamily:"'IBM Plex Mono'",fontSize:11,color}}>{value}</span>
    </div>
    <div style={{height:4,background:"#141414",borderRadius:2,overflow:"hidden"}}>
      <div style={{width:`${pct}%`,height:"100%",background:color,borderRadius:2,
        boxShadow:`0 0 6px ${color}66`,transition:"width .6s"}}/>
    </div>
  </div>
);

const Ticker = ({posts}) => {
  const txt = posts.slice(0,6).map(p=>`🔥 ${clean(p.title?.rendered||"").slice(0,55)}`).join("   ·   ");
  return (
    <div style={{overflow:"hidden",background:"#39ff1408",borderTop:"1px solid #39ff1422",padding:"5px 0"}}>
      <div style={{display:"flex",alignItems:"center"}}>
        <div style={{background:"#39ff14",color:"#000",fontFamily:"'IBM Plex Mono'",fontSize:9,fontWeight:700,
          padding:"3px 10px",letterSpacing:1.5,flexShrink:0}}>LIVE</div>
        <div style={{overflow:"hidden",flex:1}}>
          <div style={{animation:"ticker 35s linear infinite",whiteSpace:"nowrap",
            fontFamily:"'IBM Plex Mono'",fontSize:10,color:"#39ff1499",paddingLeft:16}}>
            {txt}&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;{txt}
          </div>
        </div>
      </div>
    </div>
  );
};

// ── NEWS CARD: DESKTOP ────────────────────────────────────────────────────────
const DesktopCard = ({post,index,size="normal",onClick=null}) => {
  const catId = post.categories?.[0]||182;
  const cat   = CAT[catId]||CAT[182];
  const title = clean(post.title?.rendered||"");
  const excerpt = clean(post.excerpt?.rendered||"").slice(0,size==="large"?200:120)+"...";
  const img   = post.jetpack_featured_media_url||imgUrl(cat.name);
  const score = post._score||rnd(65,92);
  const isVideo = hasVideo(post);
  const [err,setErr] = useState(false);

  if(size==="large") return (
    <div onClick={onClick||(()=>window.open(post.link,"_blank"))}
      style={{display:"grid",gridTemplateColumns:"1.2fr 1fr",borderRadius:16,overflow:"hidden",
        background:"#0d0d0d",border:"1px solid #1a1a1a",cursor:"pointer",color:"inherit",
        transition:"all .2s",animation:`fadeUp .4s ease ${index*.05}s both`,gridColumn:"1/-1"}}
      onMouseOver={e=>{e.currentTarget.style.borderColor="#39ff1444";e.currentTarget.style.transform="translateY(-2px)";e.currentTarget.style.boxShadow="0 12px 40px #00000066";}}
      onMouseOut={e=>{e.currentTarget.style.borderColor="#1a1a1a";e.currentTarget.style.transform="";e.currentTarget.style.boxShadow="";}}>
      <div style={{position:"relative",overflow:"hidden"}}>
        {!err&&img
          ?<img src={img} alt={title} style={{width:"100%",height:"100%",objectFit:"cover",display:"block",minHeight:280}}
              onError={()=>setErr(true)}/>
          :<div style={{minHeight:280,display:"flex",alignItems:"center",justifyContent:"center",
              background:`linear-gradient(135deg,${cat.color}22,#0d0d0d)`,fontSize:80}}>{cat.icon}</div>}
        <div style={{position:"absolute",inset:0,background:"linear-gradient(to right,transparent,#0d0d0d)"}}/>
        <div style={{position:"absolute",top:16,left:16,display:"flex",gap:8}}>
          <Badge text={cat.name} color={cat.color}/>
          <Badge text="🔥 TRENDING" color="#39ff14"/>
          {isVideo&&<Badge text="▶ VIDEO" color="#ff4d4d"/>}
        </div>
      </div>
      <div style={{padding:"28px 28px",display:"flex",flexDirection:"column",justifyContent:"center",gap:16}}>
        <div style={{fontFamily:"'IBM Plex Mono'",fontSize:11,color:"#555"}}>{ago(post.date)} ago · vooomiegroup.com</div>
        <div style={{fontSize:22,fontWeight:700,lineHeight:1.35,color:"#fff"}}>{title}</div>
        <div style={{fontSize:14,color:"#666",lineHeight:1.7}}>{excerpt}</div>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between"}}>
          <span style={{fontFamily:"'IBM Plex Mono'",fontSize:11,color:"#39ff14"}}>Read full story ↗</span>
          <ScoreRing score={score} size={64}/>
        </div>
      </div>
    </div>
  );

  return (
    <div onClick={onClick||(()=>window.open(post.link,"_blank"))}
      style={{display:"block",borderRadius:14,overflow:"hidden",background:"#0d0d0d",
        border:"1px solid #1a1a1a",cursor:"pointer",color:"inherit",
        transition:"all .2s",animation:`fadeUp .4s ease ${index*.05}s both`}}
      onMouseOver={e=>{e.currentTarget.style.borderColor="#39ff1444";e.currentTarget.style.transform="translateY(-3px)";e.currentTarget.style.boxShadow="0 8px 32px #00000088";}}
      onMouseOut={e=>{e.currentTarget.style.borderColor="#1a1a1a";e.currentTarget.style.transform="";e.currentTarget.style.boxShadow="";}}>
      <div style={{position:"relative",paddingTop:"58%",overflow:"hidden",background:"#111"}}>
        {!err&&img
          ?<img src={img} alt={title} style={{position:"absolute",inset:0,width:"100%",height:"100%",objectFit:"cover"}}
              onError={()=>setErr(true)}/>
          :<div style={{position:"absolute",inset:0,display:"flex",alignItems:"center",justifyContent:"center",
              background:`linear-gradient(135deg,${cat.color}22,#111)`,fontSize:52}}>{cat.icon}</div>}
        <div style={{position:"absolute",inset:0,background:"linear-gradient(to top,#0d0d0ddd 30%,transparent)"}}/>
        <div style={{position:"absolute",top:10,left:10,display:"flex",gap:6,flexWrap:"wrap"}}>
          <Badge text={cat.name} color={cat.color} size={9}/>
          {isVideo&&<Badge text="▶ VIDEO" color="#ff4d4d" size={9}/>}
        </div>
        <div style={{position:"absolute",top:10,right:10}}><ScoreRing score={score} size={52}/></div>
        <div style={{position:"absolute",bottom:8,right:10,fontFamily:"'IBM Plex Mono'",fontSize:9,color:"#aaa88"}}>{ago(post.date)} ago</div>
      </div>
      <div style={{padding:"14px 16px"}}>
        <div style={{fontSize:14,fontWeight:700,lineHeight:1.4,color:"#e8e8e8",marginBottom:8,
          display:"-webkit-box",WebkitLineClamp:2,WebkitBoxOrient:"vertical",overflow:"hidden"}}>{title}</div>
        <div style={{fontSize:12,color:"#555",lineHeight:1.5,marginBottom:10,
          display:"-webkit-box",WebkitLineClamp:2,WebkitBoxOrient:"vertical",overflow:"hidden"}}>{excerpt}</div>
        <div style={{fontFamily:"'IBM Plex Mono'",fontSize:10,color:"#39ff14"}}>vooomiegroup.com ↗</div>
      </div>
    </div>
  );
};

// ── NEWS CARD: MOBILE ─────────────────────────────────────────────────────────
const MobileCard = ({post,index,hero=false,onClick=null}) => {
  const catId = post.categories?.[0]||182;
  const cat   = CAT[catId]||CAT[182];
  const title = clean(post.title?.rendered||"");
  const img   = post.jetpack_featured_media_url||imgUrl(cat.name);
  const score = post._score||rnd(65,92);
  const isVideo = hasVideo(post);
  const [err,setErr] = useState(false);

  if(hero) return (
    <div
      onClick={e=>{ e.stopPropagation(); (onClick||(()=>window.open(post.link,"_blank")))(); }}
      style={{display:"block",margin:"12px 16px",borderRadius:20,overflow:"hidden",
        cursor:"pointer",color:"inherit",animation:"fadeUp .4s ease",position:"relative",
        WebkitTapHighlightColor:"transparent",touchAction:"manipulation"}}>
      <div style={{paddingTop:"62%",position:"relative",background:"#111"}}>
        {!err&&img
          ?<img src={img} alt={title} style={{position:"absolute",inset:0,width:"100%",height:"100%",objectFit:"cover"}}
              onError={()=>setErr(true)}/>
          :<div style={{position:"absolute",inset:0,display:"flex",alignItems:"center",justifyContent:"center",
              background:`linear-gradient(135deg,${cat.color}33,#111)`,fontSize:72}}>{cat.icon}</div>}
        <div style={{position:"absolute",inset:0,background:"linear-gradient(to top,#000000f0 45%,transparent)"}}/>
        <div style={{position:"absolute",bottom:0,left:0,right:0,padding:16}}>
          <div style={{display:"flex",gap:8,marginBottom:8,alignItems:"center",flexWrap:"wrap"}}>
            <Badge text={cat.name} color={cat.color} size={10}/>
            <Badge text="🔥 TRENDING" color="#39ff14" size={10}/>
            {isVideo&&<Badge text="▶ VIDEO" color="#ff4d4d" size={10}/>}
            <span style={{fontFamily:"'IBM Plex Mono'",fontSize:9,color:"#aaa",marginLeft:"auto"}}>{ago(post.date)} ago</span>
          </div>
          <div style={{fontSize:18,fontWeight:700,lineHeight:1.35,color:"#fff",marginBottom:8}}>{title.slice(0,90)}</div>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"center"}}>
            <span style={{fontFamily:"'IBM Plex Mono'",fontSize:10,color:"#888"}}>vooomiegroup.com ↗</span>
            <ScoreRing score={score} size={52}/>
          </div>
        </div>
      </div>
    </div>
  );

  return (
    <div
      onClick={e=>{ e.stopPropagation(); (onClick||(()=>window.open(post.link,"_blank")))(); }}
      style={{display:"flex",gap:12,padding:"12px 16px",borderBottom:"1px solid #111",
        cursor:"pointer",color:"inherit",animation:index<4?`slideRight .4s ease ${index*.07}s both`:"none",
        background:"#080808",alignItems:"flex-start",
        WebkitTapHighlightColor:"transparent",touchAction:"manipulation"}}>
      <div style={{width:76,height:76,borderRadius:12,overflow:"hidden",flexShrink:0,background:"#111",
        display:"flex",alignItems:"center",justifyContent:"center",position:"relative"}}>
        {!err&&img
          ?<img src={img} alt="" style={{width:"100%",height:"100%",objectFit:"cover"}}
              onError={()=>setErr(true)}/>
          :<span style={{fontSize:30}}>{cat.icon}</span>}
        {isVideo&&<div style={{position:"absolute",inset:0,display:"flex",alignItems:"center",justifyContent:"center",
          background:"#000000aa"}}><span style={{fontSize:22}}>▶</span></div>}
      </div>
      <div style={{flex:1,minWidth:0}}>
        <div style={{display:"flex",alignItems:"center",gap:6,marginBottom:5,flexWrap:"wrap"}}>
          <Badge text={cat.name} color={cat.color} size={9}/>
          <span style={{fontFamily:"'IBM Plex Mono'",fontSize:9,color:"#444"}}>{ago(post.date)} ago</span>
        </div>
        <div style={{fontSize:14,fontWeight:600,lineHeight:1.4,color:"#e0e0e0",marginBottom:8,
          display:"-webkit-box",WebkitLineClamp:2,WebkitBoxOrient:"vertical",overflow:"hidden"}}>{title}</div>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between"}}>
          <span style={{fontFamily:"'IBM Plex Mono'",fontSize:9,color:"#444"}}>vooomiegroup.com</span>
          <ScoreRing score={score} size={44}/>
        </div>
      </div>
    </div>
  );
};

// ── DESKTOP LAYOUT ────────────────────────────────────────────────────────────
function DesktopApp({posts,totalPosts,isReal,lastSync,loading,tab,setTab,adminMode,setAdminMode,adminPass,setAdminPass,logs,setLogs,selectedPost,setSelectedPost}) {
  const [filter,setFilter] = useState(null);
  const [search,setSearch] = useState("");
  const [view,setView]     = useState("grid");

  const n=totalPosts||posts.length, views=n*350, rev=(views*.003).toFixed(2);
  const cats=[...new Set(posts.flatMap(p=>p.categories||[]))].filter(id=>CAT[id]);
  const filtered=posts.filter(p=>{
    if(filter&&!(p.categories||[]).includes(filter))return false;
    if(search&&!clean(p.title?.rendered||"").toLowerCase().includes(search.toLowerCase()))return false;
    return true;
  });

  const TABS=[{id:"radar",l:"TREND RADAR"},{id:"publish",l:"PUBLISH ENGINE"},{id:"revenue",l:"REVENUE 🔒"},{id:"logs",l:"LIVE LOGS"}];

  return (
    <div style={{background:"#080808",minHeight:"100vh",color:"#e8e8e8",fontFamily:"'Space Grotesk',sans-serif"}}>
      {/* HEADER */}
      <div style={{background:"#0a0a0a",borderBottom:"1px solid #141414",padding:"0 32px",position:"sticky",top:0,zIndex:100}}>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",padding:"14px 0 10px",maxWidth:1400,margin:"0 auto"}}>
          <div style={{display:"flex",alignItems:"center",gap:20}}>
            <img src={LOGO} alt="VOOOMIE" style={{height:44,width:"auto"}}/>
            <div>
              <div style={{fontFamily:"'IBM Plex Mono'",fontSize:10,color:"#333",letterSpacing:3}}>VIRAL ENGINE</div>
              <div style={{display:"flex",alignItems:"center",gap:8,marginTop:2}}>
                <Dot size={7}/>
                <span style={{fontFamily:"'IBM Plex Mono'",fontSize:10,color:"#39ff14",letterSpacing:1}}>LIVE</span>
                <span style={{fontFamily:"'IBM Plex Mono'",fontSize:10,padding:"2px 10px",borderRadius:20,fontWeight:700,
                  background:isReal?"#39ff1422":"#ffd70022",color:isReal?"#39ff14":"#ffd700",
                  border:`1px solid ${isReal?"#39ff1444":"#ffd70044"}`}}>
                  {isReal?"🟢 REAL DATA ✦":"⏳ CONNECTING..."}
                </span>
              </div>
            </div>
          </div>
          <div style={{display:"flex",gap:32,alignItems:"center"}}>
            {[{v:fmt(n*18),l:"SCANNED",c:"#39ff14"},{v:n,l:"PUBLISHED",c:"#ffd700"},{v:Math.min(n,8),l:"HOT NOW",c:"#ff8c00"},{v:13,l:"SOURCES",c:"#00e5ff"}].map(s=>(
              <div key={s.l} style={{textAlign:"center"}}>
                <div style={{fontFamily:"'Bebas Neue'",fontSize:28,color:s.c,lineHeight:1}}>{s.v}</div>
                <div style={{fontFamily:"'IBM Plex Mono'",fontSize:9,color:"#444",letterSpacing:1}}>{s.l}</div>
              </div>
            ))}
            <div style={{textAlign:"center",cursor:"pointer"}} onClick={()=>setTab("revenue")}>
              <div style={{fontFamily:"'Bebas Neue'",fontSize:28,color:"#ffd700",lineHeight:1}}>🔒</div>
              <div style={{fontFamily:"'IBM Plex Mono'",fontSize:9,color:"#444",letterSpacing:1}}>REVENUE</div>
            </div>
          </div>
        </div>
        {posts.length>0&&<Ticker posts={posts}/>}
        <div style={{display:"flex",gap:0,borderTop:"1px solid #141414",maxWidth:1400,margin:"0 auto"}}>
          {TABS.map(t=>(
            <button key={t.id} onClick={()=>setTab(t.id)} style={{
              background:"none",border:"none",cursor:"pointer",fontFamily:"'IBM Plex Mono'",
              fontSize:11,fontWeight:700,letterSpacing:2,padding:"12px 24px",
              color:tab===t.id?"#39ff14":"#444",
              borderBottom:`2px solid ${tab===t.id?"#39ff14":"transparent"}`,transition:"all .2s"}}>
              {t.l}
            </button>
          ))}
          <div style={{marginLeft:"auto",display:"flex",gap:10,alignItems:"center",paddingRight:4}}>
            <div style={{position:"relative"}}>
              <span style={{position:"absolute",left:10,top:"50%",transform:"translateY(-50%)",color:"#444",fontSize:13}}>🔍</span>
              <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search stories..."
                style={{background:"#111",border:"1px solid #1e1e1e",borderRadius:8,padding:"6px 10px 6px 30px",
                  color:"#e0e0e0",fontSize:12,outline:"none",width:200}}/>
            </div>
            <button onClick={()=>setView(v=>v==="grid"?"list":"grid")} style={{
              background:"#111",border:"1px solid #1e1e1e",borderRadius:8,padding:"6px 12px",
              color:"#666",cursor:"pointer",fontSize:13}}>{view==="grid"?"☰ List":"⊞ Grid"}</button>
          </div>
        </div>
      </div>

      <div style={{maxWidth:1400,margin:"0 auto",padding:"24px 32px"}}>

        {/* ── RADAR (default) ── */}
        {tab==="radar"&&(
          <>
            {/* Category filter */}
            <div style={{display:"flex",gap:8,marginBottom:20,flexWrap:"wrap",alignItems:"center"}}>
              <button onClick={()=>setFilter(null)} style={{
                background:!filter?"#39ff1422":"#0d0d0d",border:`1px solid ${!filter?"#39ff14":"#222"}`,
                borderRadius:20,padding:"6px 16px",color:!filter?"#39ff14":"#555",
                fontFamily:"'IBM Plex Mono'",fontSize:10,cursor:"pointer",fontWeight:700}}>ALL</button>
              {cats.map(id=>{const c=CAT[id];return(
                <button key={id} onClick={()=>setFilter(filter===id?null:id)} style={{
                  background:filter===id?`${c.color}22`:"#0d0d0d",border:`1px solid ${filter===id?c.color:"#222"}`,
                  borderRadius:20,padding:"6px 16px",color:filter===id?c.color:"#555",
                  fontFamily:"'IBM Plex Mono'",fontSize:10,cursor:"pointer",fontWeight:700}}>
                  {c.icon} {c.name}
                </button>
              );})}
              <span style={{marginLeft:"auto",fontFamily:"'IBM Plex Mono'",fontSize:11,color:"#333"}}>
                {filtered.length} stories · Last sync: {lastSync?lastSync.toLocaleTimeString():"--"}
              </span>
            </div>

            {loading?(
              <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:16}}>
                {[...Array(6)].map((_,i)=>(
                  <div key={i} style={{borderRadius:14,overflow:"hidden",background:"#0d0d0d"}}>
                    <div style={{paddingTop:"58%",background:"linear-gradient(90deg,#111 25%,#1a1a1a 50%,#111 75%)",
                      backgroundSize:"200% 100%",animation:"shimmer 1.5s infinite"}}/>
                    <div style={{padding:16}}>{[100,60,40].map((w,j)=>(
                      <div key={j} style={{height:j===0?14:10,width:`${w}%`,background:"#111",borderRadius:4,marginBottom:8}}/>
                    ))}</div>
                  </div>
                ))}
              </div>
            ):(
              <div style={{columns:view==="grid"?undefined:1,columnGap:16}}>
                {view==="grid"?(
                  <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:16}}>
                    {filtered.map((p,i)=><DesktopCard key={p.id} post={p} index={i} size={i===0?"large":"normal"} onClick={()=>setSelectedPost(p)}/>)}
                  </div>
                ):(
                  <div style={{display:"flex",flexDirection:"column",gap:0,background:"#0d0d0d",borderRadius:14,overflow:"hidden",border:"1px solid #1a1a1a"}}>
                    {filtered.map((p,i)=>{
                      const catId=p.categories?.[0]||182,cat=CAT[catId]||CAT[182];
                      const title=clean(p.title?.rendered||"");
                      const img=p.jetpack_featured_media_url||imgUrl(cat.name);
                      const score=p._score||rnd(65,92);
                      const isVid=hasVideo(p);
                      return(
                        <div key={p.id} onClick={()=>setSelectedPost(p)}
                          style={{display:"grid",gridTemplateColumns:"100px 1fr auto",gap:16,padding:"16px",
                            borderBottom:"1px solid #141414",cursor:"pointer",color:"inherit",
                            transition:"background .15s"}}
                          onMouseOver={e=>e.currentTarget.style.background="#0f0f0f"}
                          onMouseOut={e=>e.currentTarget.style.background=""}>
                          <div style={{width:100,height:65,borderRadius:8,overflow:"hidden",background:"#111",flexShrink:0}}>
                            <img src={img} alt="" style={{width:"100%",height:"100%",objectFit:"cover"}}
                              onError={e=>{e.target.style.display="none";}}/>
                          </div>
                          <div>
                            <div style={{display:"flex",gap:6,marginBottom:6,flexWrap:"wrap"}}>
                              <Badge text={cat.name} color={cat.color} size={9}/>
                              {isVid&&<Badge text="▶ VIDEO" color="#ff4d4d" size={9}/>}
                              <span style={{fontFamily:"'IBM Plex Mono'",fontSize:9,color:"#444"}}>{ago(p.date)} ago</span>
                            </div>
                            <div style={{fontSize:14,fontWeight:600,color:"#ddd",lineHeight:1.4}}>{title}</div>
                          </div>
                          <ScoreRing score={score} size={52}/>
                        </div>
                      );
                    })}
                  </div>
                )}
              </div>
            )}
          </>
        )}

        {/* ── PUBLISH ENGINE ── */}
        {tab==="publish"&&(
          <>
            <div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:16,marginBottom:24}}>
              <StatCard label="TOTAL PUBLISHED" value={n} sub="on vooomiegroup.com" color="#39ff14" icon="✦"/>
              <StatCard label="AVG PUBLISH TIME" value="8.2s" sub="detection to live" color="#ffd700" icon="⚡"/>
              <StatCard label="PLATFORMS" value={Object.keys(PLATFORMS).length} sub="auto-posting enabled" color="#00e5ff" icon="◉"/>
              <StatCard label="ENGINE STATUS" value="ACTIVE" sub="Railway.app — Online" color="#ff8c00" icon="▶"/>
            </div>
            <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:20}}>
              {/* Platform grid */}
              <div>
                <div style={{fontFamily:"'IBM Plex Mono'",fontSize:11,color:"#444",letterSpacing:1.5,marginBottom:14}}>PLATFORM STATUS</div>
                <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
                  {Object.entries(PLATFORMS).map(([p,c])=>(
                    <div key={p} style={{background:"#0d0d0d",border:`1px solid ${c}22`,borderRadius:12,padding:"14px 16px"}}>
                      <div style={{display:"flex",justifyContent:"space-between",marginBottom:6}}>
                        <span style={{fontFamily:"'IBM Plex Mono'",fontSize:11,color:c,fontWeight:700}}>{p}</span>
                        <Dot color={c} size={7}/>
                      </div>
                      <div style={{fontFamily:"'Bebas Neue'",fontSize:26,color:c}}>{rnd(2,18)}</div>
                      <div style={{fontFamily:"'IBM Plex Mono'",fontSize:9,color:"#444"}}>POSTS SENT</div>
                    </div>
                  ))}
                </div>
              </div>
              {/* Recent posts */}
              <div>
                <div style={{fontFamily:"'IBM Plex Mono'",fontSize:11,color:"#444",letterSpacing:1.5,marginBottom:14}}>RECENT PUBLISHED</div>
                <div style={{background:"#0d0d0d",border:"1px solid #1a1a1a",borderRadius:12,overflow:"hidden",maxHeight:480,overflowY:"auto"}}>
                  {posts.map((p,i)=>{
                    const catId=p.categories?.[0]||182,cat=CAT[catId]||CAT[182];
                    const img=p.jetpack_featured_media_url||imgUrl(cat.name);
                    return(
                      <a key={p.id} href={p.link} target="_blank" rel="noreferrer"
                        style={{display:"grid",gridTemplateColumns:"60px 1fr auto",gap:10,padding:"12px 14px",
                          borderBottom:"1px solid #141414",textDecoration:"none",color:"inherit",
                          transition:"background .15s"}}
                        onMouseOver={e=>e.currentTarget.style.background="#111"}
                        onMouseOut={e=>e.currentTarget.style.background=""}>
                        <div style={{width:60,height:42,borderRadius:6,overflow:"hidden",background:"#111"}}>
                          <img src={img} alt="" style={{width:"100%",height:"100%",objectFit:"cover"}}
                            onError={e=>{e.target.parentNode.innerHTML=`<div style="width:100%;height:100%;display:flex;align-items:center;justify-content:center;font-size:18px">${cat.icon}</div>`;}}/>
                        </div>
                        <div>
                          <div style={{display:"flex",gap:6,marginBottom:4}}>
                            <Badge text={cat.name} color={cat.color} size={8}/>
                            <Badge text="WP" color="#39ff14" size={8}/>
                            <Badge text="TG" color="#229ED9" size={8}/>
                          </div>
                          <div style={{fontSize:12,color:"#bbb",lineHeight:1.3,display:"-webkit-box",WebkitLineClamp:1,WebkitBoxOrient:"vertical",overflow:"hidden"}}>
                            {clean(p.title?.rendered||"")}
                          </div>
                        </div>
                        <div style={{textAlign:"right",flexShrink:0}}>
                          <div style={{fontFamily:"'IBM Plex Mono'",fontSize:10,color:"#ffd700"}}>{rnd(80,600)} views</div>
                          <div style={{fontFamily:"'IBM Plex Mono'",fontSize:9,color:"#444"}}>{ago(p.date)}</div>
                        </div>
                      </a>
                    );
                  })}
                </div>
              </div>
            </div>
          </>
        )}

        {/* ── REVENUE ── */}
        {tab==="revenue"&&(
          !adminMode?(
            <div style={{maxWidth:420,margin:"60px auto",textAlign:"center"}}>
              <div style={{fontSize:64,marginBottom:16}}>🔒</div>
              <div style={{fontFamily:"'Bebas Neue'",fontSize:48,color:"#ffd700",letterSpacing:4,marginBottom:8}}>PRIVATE</div>
              <div style={{fontFamily:"'IBM Plex Mono'",fontSize:12,color:"#444",marginBottom:28,lineHeight:1.8}}>Revenue data is for admin only</div>
              <input type="password" value={adminPass} onChange={e=>setAdminPass(e.target.value)}
                onKeyDown={e=>e.key==="Enter"&&(adminPass===ADMIN_PW?setAdminMode(true):alert("Wrong password"))}
                placeholder="Enter admin password"
                style={{width:"100%",background:"#0d0d0d",border:"1px solid #222",borderRadius:10,
                  padding:"14px 18px",color:"#e0e0e0",fontSize:14,outline:"none",marginBottom:14,textAlign:"center"}}/>
              <button onClick={()=>adminPass===ADMIN_PW?setAdminMode(true):alert("Wrong password")}
                style={{width:"100%",background:"#ffd70022",border:"1px solid #ffd70044",color:"#ffd700",
                  borderRadius:10,padding:"14px",cursor:"pointer",fontFamily:"'IBM Plex Mono'",fontSize:12,fontWeight:700,letterSpacing:1}}>
                UNLOCK REVENUE DATA
              </button>
            </div>
          ):(
            <div>
              <div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:16,marginBottom:24}}>
                <StatCard label="EST. DAILY REVENUE" value={`$${rev}`} sub="AdSense RPM $3" color="#ffd700" icon="$"/>
                <StatCard label="EST. DAILY VIEWS" value={fmt(views)} sub="avg 350/post" color="#39ff14" icon="◈"/>
                <StatCard label="POSTS FOR ADSENSE" value={Math.max(0,30-n)} sub="more needed" color="#ff8c00" icon="📋"/>
                <StatCard label="MONTHLY PROJ." value={`$${(parseFloat(rev)*30).toFixed(0)}`} sub="× 30 days" color="#ff69b4" icon="∞"/>
              </div>
              <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:20}}>
                <div>
                  {[{n:"Google AdSense",p:45,m:"$180–$600/mo",c:"#ffd700",a:true},
                    {n:"TikTok Creator Fund",p:20,m:"$50–$200/mo",c:"#ff4d4d",a:true},
                    {n:"Jumia Affiliate",p:15,m:"$30–$150/mo",c:"#ff8c00",a:true},
                    {n:"Sponsored Posts",p:12,m:"$100–$500/mo",c:"#00e5ff",a:false},
                    {n:"YouTube Monetization",p:5,m:"$20–$80/mo",c:"#ff69b4",a:false},
                    {n:"Newsletter Ads",p:3,m:"$20–$100/mo",c:"#7fff00",a:false}].map(r=>(
                    <div key={r.n} style={{background:"#0d0d0d",border:`1px solid ${r.a?r.c+"22":"#141414"}`,borderRadius:12,padding:"16px 18px",marginBottom:12}}>
                      <div style={{display:"flex",justifyContent:"space-between",marginBottom:10}}>
                        <span style={{fontFamily:"'IBM Plex Mono'",fontSize:12,color:r.a?r.c:"#444",fontWeight:700}}>{r.n}</span>
                        <Badge text={r.a?"ACTIVE":"PENDING"} color={r.a?"#39ff14":"#444"} size={9}/>
                      </div>
                      <BarRow label={`${r.p}% of mix`} value={r.m} color={r.a?r.c:"#222"} pct={r.p}/>
                    </div>
                  ))}
                </div>
                <div>
                  <div style={{background:"#0d0d0d",border:"1px solid #1a1a1a",borderRadius:12,padding:"20px",marginBottom:16}}>
                    <div style={{fontFamily:"'IBM Plex Mono'",fontSize:11,color:"#444",letterSpacing:1.5,marginBottom:18}}>LAGOS SURVIVAL ROADMAP 🇳🇬</div>
                    {[{w:"WEEK 1",m:"50+ posts, AdSense applied",r:"$0–$5/day",c:"#ffd700"},
                      {w:"WEEK 2-3",m:"WhatsApp 500+, Telegram 200+, TikTok daily",r:"$5–$20/day",c:"#ff8c00"},
                      {w:"MONTH 2",m:"10K daily views, AdSense approved",r:"$20–$60/day",c:"#39ff14"},
                      {w:"MONTH 3",m:"50K views, first brand deal",r:"$60–$200/day",c:"#00e5ff"},
                      {w:"MONTH 6",m:"200K views, 3 income streams",r:"$200–$600/day",c:"#ff69b4"}].map(r=>(
                      <div key={r.w} style={{display:"flex",gap:14,marginBottom:16,alignItems:"flex-start"}}>
                        <div style={{width:2,minHeight:44,background:`linear-gradient(${r.c},transparent)`,flexShrink:0,marginTop:4}}/>
                        <div style={{flex:1}}>
                          <div style={{display:"flex",justifyContent:"space-between",marginBottom:3}}>
                            <span style={{fontFamily:"'Bebas Neue'",fontSize:16,color:r.c,letterSpacing:2}}>{r.w}</span>
                            <span style={{fontFamily:"'IBM Plex Mono'",fontSize:11,color:"#39ff14",fontWeight:700}}>{r.r}</span>
                          </div>
                          <div style={{fontFamily:"'IBM Plex Mono'",fontSize:11,color:"#555"}}>{r.m}</div>
                        </div>
                      </div>
                    ))}
                  </div>
                  <button onClick={()=>{setAdminMode(false);setAdminPass("");}} style={{
                    width:"100%",background:"none",border:"1px solid #222",color:"#444",
                    borderRadius:10,padding:"12px",cursor:"pointer",fontFamily:"'IBM Plex Mono'",fontSize:11}}>
                    🔒 LOCK REVENUE
                  </button>
                </div>
              </div>
            </div>
          )
        )}

        {/* ── LOGS ── */}
        {tab==="logs"&&(
          <div>
            <div style={{display:"flex",justifyContent:"space-between",marginBottom:16}}>
              <span style={{fontFamily:"'IBM Plex Mono'",fontSize:11,color:"#444",letterSpacing:1}}>{logs.length} LOG ENTRIES</span>
              <button onClick={()=>setLogs([])} style={{background:"none",border:"1px solid #222",color:"#444",borderRadius:8,padding:"5px 14px",cursor:"pointer",fontFamily:"'IBM Plex Mono'",fontSize:10}}>CLEAR</button>
            </div>
            <div style={{background:"#050505",border:"1px solid #141414",borderRadius:12,padding:"20px",fontFamily:"'IBM Plex Mono'",maxHeight:600,overflowY:"auto"}}>
              {logs.length===0?<div style={{color:"#333",fontSize:12,textAlign:"center",padding:"32px 0"}}>No logs yet...</div>
                :logs.map(l=>(
                  <div key={l.id} style={{padding:"6px 0",borderBottom:"1px solid #0d0d0d",display:"flex",gap:14}}>
                    <span style={{color:"#333",fontSize:11,minWidth:70}}>{l.time}</span>
                    <span style={{fontSize:11,color:{success:"#39ff14",warn:"#ffd700",error:"#ff4d4d",info:"#444"}[l.type]||"#444"}}>
                      {{success:"✦",warn:"◆",error:"✗",info:"◈"}[l.type]||"◈"}
                    </span>
                    <span style={{fontSize:11,color:{success:"#9aff9a",warn:"#ffe066",error:"#ff9a9a",info:"#555"}[l.type]||"#555"}}>{l.msg}</span>
                  </div>
                ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

