// ── ROOT ──────────────────────────────────────────────────────────────────────
export default function App() {
  const isMobile = useIsMobile();
  const [posts,setPosts]       = useState([]);
  const [isReal,setIsReal]     = useState(false);
  const [loading,setLoading]   = useState(true);
  const [lastSync,setLastSync] = useState(null);
  const [tab,setTab]           = useState(isMobile?"home":"radar");
  const [adminMode,setAdminMode] = useState(false);
  const [adminPass,setAdminPass] = useState("");
  const [logs,setLogs]         = useState([]);
  const [selectedPost,setSelectedPost] = useState(null);
  const prevCount = useRef(0);

  const addLog = useCallback((msg,type="info")=>{
    setLogs(p=>[{id:Date.now()+Math.random(),msg,type,time:new Date().toLocaleTimeString()},...p].slice(0,80));
  },[]);

  const [totalPosts, setTotalPosts] = useState(0);

  const fetchPosts = useCallback(async()=>{
    // Try multiple methods to fetch WordPress posts
    const urls = [
      WP_API+"&_="+Date.now(),
      // Fallback: try without cache-busting
      WP_API,
    ];

    for(const url of urls){
      try {
        const res = await fetch(url, {
          cache:"no-store",
          mode:"cors",
          headers:{
            "Accept":"application/json",
            "Content-Type":"application/json",
          }
        });
        if(!res.ok) throw new Error("HTTP "+res.status);

        const wpTotal = parseInt(res.headers.get("X-WP-Total")||"0");
        if(wpTotal > 0) setTotalPosts(wpTotal);

        const data = await res.json();
        if(!Array.isArray(data)||!data.length) throw new Error("Empty");

        const scored = data.map(p=>({...p,_score:rnd(65,92),_views:rnd(80,600)}));
        setPosts(scored);
        setIsReal(true);
        setLoading(false);
        setLastSync(new Date());
        const realTotal = wpTotal||data.length;
        if(prevCount.current>0&&realTotal>prevCount.current){
          addLog(`${realTotal-prevCount.current} new post(s) detected!`,"success");
        }
        prevCount.current = realTotal;
        addLog(`✦ Synced ${data.length} posts · ${realTotal} total on vooomiegroup.com`,"success");
        return; // success — stop trying
      } catch(e){
        addLog(`Fetch attempt failed: ${e.message}`,"warn");
      }
    }
    // All attempts failed
    setLoading(false);
    addLog("Could not connect to WordPress — check CORS plugin is active","error");
  },[addLog]);

  useEffect(()=>{ fetchPosts(); const t=setInterval(fetchPosts,30000); return()=>clearInterval(t); },[fetchPosts]);

  const CSS = `
    @keyframes pulse{0%,100%{opacity:1}50%{opacity:.3}}
    @keyframes glow{0%,100%{filter:drop-shadow(0 0 6px #39ff1488)}50%{filter:drop-shadow(0 0 18px #39ff14cc)}}
    @keyframes fadeUp{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:translateY(0)}}
    @keyframes slideRight{from{opacity:0;transform:translateX(-14px)}to{opacity:1;transform:translateX(0)}}
    @keyframes ticker{0%{transform:translateX(0)}100%{transform:translateX(-50%)}}
    @keyframes shimmer{0%{background-position:-200% 0}100%{background-position:200% 0}}
    *{box-sizing:border-box;margin:0;padding:0;-webkit-tap-highlight-color:transparent}
    ::-webkit-scrollbar{width:3px;height:3px}
    ::-webkit-scrollbar-track{background:#0a0a0a}
    ::-webkit-scrollbar-thumb{background:#222;border-radius:2px}
    a{text-decoration:none;color:inherit}
    input,button{font-family:'Space Grotesk',sans-serif}
  `;

  const shared = {posts,totalPosts,isReal,lastSync,loading,tab,setTab,adminMode,setAdminMode,adminPass,setAdminPass,logs,setLogs,selectedPost,setSelectedPost};

  return (
    <>
      <style>{CSS}</style>
      {isMobile ? <MobileApp {...shared}/> : <DesktopApp {...shared}/>}
      {selectedPost && <PostReader post={selectedPost} onClose={()=>setSelectedPost(null)}/>}
    </>
  );
}
